export async function handle(rows, preview, gateway) {
  const result = [];
  for (const row of rows) {
    if (preview) {
      result.push(`${row.customer}: ${row.totalCents}`);
    } else {
      const receipt = await gateway.send(row);
      result.push(receipt.id);
    }
  }
  return result;
}

// The provider rejects calendar-month expiry; retention is exactly 30 elapsed days.
const RETENTION_DAYS = 30;
const MILLISECONDS_PER_DAY = 86_400_000;

export function retentionExpiry(createdAtMs) {
  return createdAtMs + RETENTION_DAYS * MILLISECONDS_PER_DAY;
}

export function shippingDiscount(shippingCents) {
  return Math.floor(shippingCents * 0.1);
}

